	('7cf3a94b-a880-4c81-942a-a78608ba503d', 'Real Estate Agencies', 'real-estate-agencies', 'Residential and commercial brokerages with active agent teams.', 'Brokerages with 5–100 agents and high inbound enquiry volume', '{"United States","United Arab Emirates",Spain}', '5-100', '{"Broker Owner","Managing Director","Head of Sales"}', 'Inbound enquiries answered late, no consistent nurture, listings admin overhead.', 'Instant lead response + viewing scheduling + nurture sequences.', NULL, '#0891b2', false, '2026-08-20 12:22:49.916159+01', '2026-08-20 12:22:49.916159+01'),
	('1e8b548a-d2fc-435c-910d-2a994491e2b8', 'Dental Practices', 'dental-practices', 'Private dental clinics and multi-site dental groups.', 'Private practices with 2+ chairs and paid patient acquisition', '{"United Kingdom","United States",Australia}', '5-40', '{"Practice Owner","Practice Manager","Principal Dentist"}', 'No-shows, reception overloaded with calls, treatment plans not followed up.', 'Automated recall, reminders and treatment plan follow-up.', NULL, '#7c3aed', false, '2026-08-20 12:22:49.916159+01', '2026-08-20 12:22:49.916159+01'),
