	('680f7d9b-d43a-4108-9f09-ce8b342ae6ba', 'Home Service Businesses', 'home-service-businesses', 'HVAC, plumbing, roofing, landscaping and similar field-service operators.', 'Operators with 5–80 field staff and phone-driven booking', '{"United States",Canada}', '5-80', '{Owner,"General Manager","Operations Manager"}', 'Missed calls become lost jobs, manual quoting, no follow-up on estimates.', 'Missed-call capture, automated quoting and estimate follow-up.', NULL, '#ea580c', false, '2026-08-20 12:22:49.916159+01', '2026-08-20 12:22:49.916159+01');;
